fn capitalize_first_letter(word: Vec<char>) -> Vec<char> {
    let mut result = Vec::with_capacity(word.len());
    
    // Handle first character
    let first_char = word[0];
    if first_char.is_uppercase() {
        result.push(first_char);
    } else {
        // Input is lowercase letter, replace with 'A'
        result.push('A');
    }
    
    // Copy the rest of the characters unchanged
    for &ch in &word[1..] {
        result.push(ch);
    }
    
    result
}